// spec: specs/ssr-seo-public.md (1.7)
// seed: tests/seed.spec.ts
// Прод, только чтение: браузер, все не-GET запросы заблокированы. Категория берётся из sitemap.
import { test, expect } from '@playwright/test';
import { readSitemap, categoryItemCount, seoBody, rootHtml, links, foundCount, blockNonGet } from './ssr-seo.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('SSR и SEO публичных страниц — hydration', () => {
  test('Фильтр категории после hydration: URL ?category=, «נמצאו N» = ItemList.numberOfItems, «назад» сохраняет фильтр #b3dc2e @desktop @prod-safe', async ({ page, request }) => {
    // Категория с ≥ 1 объявлением (первая по sitemap) и название её первой карточки из SSR-блока.
    const sm = await readSitemap(request);
    let cat = '';
    let n = 0;
    let cardName = '';
    for (const c of sm.categories) {
      const r = await categoryItemCount(request, c);
      const card = links(seoBody(rootHtml(r.html) ?? '')?.html ?? '').find((l) => l.href.includes('/businessdetail?id=') && l.text);
      if (r.n > 0 && card) { cat = c; n = r.n; cardName = card.text; break; }
    }
    expect(cat, 'категория с объявлениями в sitemap').not.toBe('');

    await blockNonGet(page);
    await page.goto('/search');
    await foundCount(page);

    // 1. Выбрать категорию в списке категорий.
    const categorySelect = page.getByRole('combobox').first();
    await expect(categorySelect).toHaveText('כל הקטגוריות');
    await categorySelect.click();
    await page.getByRole('option', { name: cat, exact: true }).click();
    await page.waitForURL((u) => u.searchParams.get('category') === cat);
    await expect.poll(() => foundCount(page), { message: '«נמצאו N» = numberOfItems' }).toBe(n);

    // 2. Открыть карточку из результатов и вернуться назад.
    await page.getByRole('link', { name: cardName }).first().click();
    await page.waitForURL(/\/businessdetail\?id=/);
    await page.goBack();
    await page.waitForURL((u) => u.pathname === '/search' && u.searchParams.get('category') === cat);
    await expect(page.getByRole('combobox').first()).toHaveText(cat);
    await expect.poll(() => foundCount(page), { message: 'после «назад» «נמצאו N» тот же' }).toBe(n);
  });
});
